/**
 * XSS and mutation-XSS corpus (PLAN §12.3 WP-15: ≥ 150 vectors, 0 escapes).
 *
 * Sources: OWASP XSS Filter Evasion Cheat Sheet, PortSwigger XSS cheat sheet, the DOMPurify and
 * sanitize-html mXSS reports (namespace confusion, raw-text elements, foster parenting, comment
 * and CDATA tricks), CommonMark/GFM link-destination edge cases, and payloads aimed at this
 * package's own features (spoilers, alerts, mentions, heading ids, YouTube facades, resolvers).
 * Every vector runs through every profile; a vector "escapes" if the rendered HTML, parsed by a
 * real HTML parser, contains any active content.
 */

export interface XssVector {
  name: string;
  input: string;
}

